# Casi limite di Creator.sol (solc 0.8.11) su chain in memoria
import json
from web3 import Web3, EthereumTesterProvider
w3 = Web3(EthereumTesterProvider()); me, other = w3.eth.accounts[0], w3.eth.accounts[1]
with open("Creator.json") as f: out = json.load(f)["Creator.sol"]
def deploy(n, *a, value=0):
    abi, bc = out[n]["abi"], out[n]["evm"]["bytecode"]["object"]
    h = w3.eth.contract(abi=abi, bytecode=bc).constructor(*a).transact({"from": me, "value": value})
    return w3.eth.contract(address=w3.eth.wait_for_transaction_receipt(h).contractAddress, abi=abi)
c = deploy("Creator")
try: c.functions.getInnerContractX().call(); print("x senza inner: ok?!")
except Exception as e: print("getInnerContractX prima di createCreated ->", type(e).__name__)
w3.eth.wait_for_transaction_receipt(c.functions.overrideCreated(other).transact({"from": other}))
print("overrideCreated chiamata da un altro account: inner =", c.functions.getInnerContractAddr().call() == other)
try: c.functions.getInnerContractX().call()
except Exception as e: print("inner = EOA, getInnerContractX ->", type(e).__name__)
eth = w3.to_wei(1, "ether")
w3.eth.wait_for_transaction_receipt(c.functions.createAndEndowCreated(1, eth).transact({"from": me, "value": 3*eth}))
print("inviati 3 ETH, endowment 1 ETH -> saldo Creator bloccato:", w3.eth.get_balance(c.address)/eth, "ETH")

