// Board.sol
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.0;

// Bacheca minimale di proposte: serve per provare la lettura degli eventi da Python
contract Board {
    struct Proposal { address proposer; uint amount; uint yes; }
    Proposal[] public proposals;
    mapping(uint => mapping(address => bool)) public voted;

    event NewProposal(uint indexed id, address indexed proposer, uint amount);
    event Voted(uint indexed id, address indexed voter);

    function propose(uint amount) external returns (uint id) {
        proposals.push(Proposal(msg.sender, amount, 0));
        id = proposals.length - 1;
        emit NewProposal(id, msg.sender, amount);
    }

    function voteYes(uint id) external {
        require(id < proposals.length, "No such proposal");
        require(!voted[id][msg.sender], "Already voted");
        voted[id][msg.sender] = true;
        proposals[id].yes += 1;
        emit Voted(id, msg.sender);
    }
}

