# Votante automatico: si accorge delle nuove proposte leggendo gli eventi NewProposal (polling di un filtro)
import json
from web3 import Web3, EthereumTesterProvider

w3 = Web3(EthereumTesterProvider())
alice, bot = w3.eth.accounts[0], w3.eth.accounts[1]
with open("Board.json") as f:
    c = json.load(f)["Board.sol"]["Board"]
h = w3.eth.contract(abi=c["abi"], bytecode=c["evm"]["bytecode"]["object"]).constructor().transact({"from": alice})
board = w3.eth.contract(address=w3.eth.wait_for_transaction_receipt(h).contractAddress, abi=c["abi"])

flt = board.events.NewProposal.create_filter(fromBlock="latest")   # filtro lato nodo (eth_newFilter)

def poll_and_vote():
    for ev in flt.get_new_entries():                                # solo gli eventi arrivati dall'ultima chiamata
        pid = ev.args.id
        print(f"  blocco {ev.blockNumber}: proposta {pid} di {ev.args.proposer[:8]}... importo {ev.args.amount}")
        if not board.functions.voted(pid, bot).call():
            w3.eth.wait_for_transaction_receipt(board.functions.voteYes(pid).transact({"from": bot}))
            print(f"  -> voto SI alla proposta {pid}")

for amount in (100, 250):
    board.functions.propose(amount).transact({"from": alice})
print("giro 1:"); poll_and_vote()
print("giro 2 (nessuna novità):"); poll_and_vote()
board.functions.propose(999).transact({"from": alice})
print("giro 3:"); poll_and_vote()
print("voti SI:", [board.functions.proposals(i).call()[2] for i in range(3)])
print("eventi Voted totali:", len(board.events.Voted.get_logs(fromBlock=0)))

